import six

__network_mode_from_robot_to_android_string_dicts = "abc"


def _network_mode_from_robot_to_android_string_prepare_dicts():
    from ta_ue_plugin_android.uepc import ue_manager_protocol
    names = list(ue_manager_protocol.UeManagerProtocol.network_mode_nums2names.values())
    dict_words = {}
    power = 1
    # I hate McCabe
    _save_names(dict_words, names, power)
    names_dict = {}
    for name in names:
        index = 0
        for word in name.split('_'):
            index += dict_words[word]
        names_dict[index] = name
    return names, dict_words, names_dict


def _save_names(dict_words, names, power):
    for name in names:
        for word in name.split('_'):
            if word not in dict_words:
                dict_words[word] = power
                power *= 2


def _network_mode_from_robot_to_android_string_get_dicts():
    global __network_mode_from_robot_to_android_string_dicts  # pylint: disable=global-statement
    if __network_mode_from_robot_to_android_string_dicts == "abc":
        __network_mode_from_robot_to_android_string_dicts = _network_mode_from_robot_to_android_string_prepare_dicts()
    return __network_mode_from_robot_to_android_string_dicts


def network_mode_from_robot_to_android_string(network_mode_args):
    """
    Convert network_mode given in keywords by agrs to android network mode format.

    Unit tests are best doc:
    ute_ue/test/test_ues/android/test_network_mode_from_robot_to_android_string.py

    :param network_mode_args:
    :return:
    """
    names, dict_words, names_dict = _network_mode_from_robot_to_android_string_get_dicts()
    if isinstance(network_mode_args, six.string_types):
        if network_mode_args in names:
            return network_mode_args
        network_mode_args = [network_mode_args]
    if not network_mode_args:
        raise ValueError("You need to give some network mode")
    index = _get_index_of_network_mode_args(dict_words, network_mode_args)
    if index in names_dict:
        return names_dict[index]
    raise ValueError()


def _get_index_of_network_mode_args(dict_words, network_mode_args):
    index = 0
    for elem in network_mode_args:
        for elem_and in elem.split('and'):
            for elem_ in elem_and.split('_'):
                elem_ = elem_.strip()
                if elem_ not in dict_words:
                    raise ValueError("Cannot recognize " + str(elem_) + ", I am able to recognize: " + ", ".join(list(dict_words.keys())))
                index += dict_words[elem_]
    return index
